private static String buildMessage(LimitType limitType, int limit) {
    switch(limitType) {
        case MAX_DEPTH:
            return "Max embedded depth reached: " + limit;
        case MAX_COUNT:
            return "Max embedded count reached: " + limit;
        default:
            return "Embedded limit reached: " + limit;
    }
}
